// @rust-js/runtime 0.0.2: the helpers the JS rust-js writes imports (ADR 0103).
// Generated by `rust-js --runtime-module`. Do not edit.
export function $traitImpl(cache, keys, make) {
  // Each key is a dictionary or a drop, held weakly: a drop made for one call
  // goes when it does. No drop, `undefined`, is keyed by this function. A
  // const parameter's value is a number or the like, which only a Map holds.
  for (let i = 0; i < keys.length - 1; i++) {
    const key = keys[i] ?? $traitImpl;
    const next = keys[i + 1] ?? $traitImpl;
    const weak = typeof next === "object" || typeof next === "function";
    if (!cache.has(key)) cache.set(key, weak ? new WeakMap() : new Map());
    cache = cache.get(key);
  }
  const key = keys[keys.length - 1] ?? $traitImpl;
  if (!cache.has(key)) cache.set(key, make());
  return cache.get(key);
}

export function $index(items, index) {
  if (index < 0 || index >= items.length) throw new Error(`index out of bounds: the len is ${items.length} but the index is ${index}`);
  return items[index];
}

export function $at(items, index) {
  if (index < 0 || index >= items.length) throw new Error(`index out of bounds: the len is ${items.length} but the index is ${index}`);
  return index;
}

// Shortest round-trip decimal, using exact rational arithmetic.
// Rust Display uses decimal notation, including for very small/large values.
// Not JS's `String(x)`, though its digits are also the shortest: when two are
// equally close, JS takes the even one (1888570120608320.2), and Rust the
// larger (1888570120608320.3).
export function $displayF64(value) {
  if (Number.isNaN(value)) return 'NaN';
  if (value === Infinity) return 'inf';
  if (value === -Infinity) return '-inf';
  const sign = value < 0 || Object.is(value, -0) ? '-' : '';
  const x = Math.abs(value);
  if (x === 0) return sign + '0';

  const bitsView = new DataView(new ArrayBuffer(8));
  bitsView.setFloat64(0, x);
  const bits = bitsView.getBigUint64(0);
  const exponentBits = Number((bits >> 52n) & 2047n);
  const fraction = bits & ((1n << 52n) - 1n);
  const significand = exponentBits === 0 ? fraction : fraction + (1n << 52n);
  const binaryExponent = exponentBits === 0 ? -1074 : exponentBits - 1023 - 52;
  const numerator = binaryExponent >= 0 ? significand << BigInt(binaryExponent) : significand;
  const denominator = binaryExponent < 0 ? 1n << BigInt(-binaryExponent) : 1n;

  // The floating-point logarithm is only an estimate; correct it exactly.
  let exponent = Math.floor(Math.log10(x));
  const atLeastPowerOfTen = e => e >= 0
    ? numerator >= denominator * 10n ** BigInt(e)
    : numerator * 10n ** BigInt(-e) >= denominator;
  while (!atLeastPowerOfTen(exponent)) exponent--;
  while (atLeastPowerOfTen(exponent + 1)) exponent++;

  for (let precision = 1; precision <= 17; precision++) {
    const power = exponent - precision + 1;
    const n = power < 0 ? numerator * 10n ** BigInt(-power) : numerator;
    const d = power > 0 ? denominator * 10n ** BigInt(power) : denominator;
    const floor = n / d;
    const rounded = floor + (2n * (n % d) >= d ? 1n : 0n);
    // The rounding interval can be asymmetric at a binary power boundary.
    let best;
    let bestDistance;
    for (const candidate of [rounded, rounded - 1n, rounded + 1n]) {
      if (candidate > 0n && Number(`${candidate}e${power}`) === x) {
        const delta = candidate * d - n;
        const distance = delta < 0n ? -delta : delta;
        if (best === undefined || distance < bestDistance || (distance === bestDistance && candidate > best)) {
          best = candidate;
          bestDistance = distance;
        }
      }
    }
    if (best !== undefined) {
      let digits = best.toString();
      let decimalPower = power;
      while (digits.endsWith('0')) {
        digits = digits.slice(0, -1);
        decimalPower++;
      }
      const point = digits.length + decimalPower;
      const body = point <= 0 ? '0.' + '0'.repeat(-point) + digits
        : point >= digits.length ? digits + '0'.repeat(point - digits.length)
        : digits.slice(0, point) + '.' + digits.slice(point);
      return sign + body;
    }
  }
  throw new Error('No f64 round-trip decimal found');
}

// The shortest digits of the positive `f32` `x` that read back as `x`, the
// nearest to it of those, as Rust's: `[digits, point]`, `x` being `0.digits`
// times 10 to `point` (ADR 0122). A decimal reads back as `x` when it's in
// `x`'s rounding interval, at an end of it only when `x`'s significand is
// even, as a tie rounds to an even one. Tested exactly: through an `f64`,
// `Math.fround(Number(text))` rounds twice, which can miss `x`.
export function $f32Digits(x) {
  const view = new DataView(new ArrayBuffer(4));
  view.setFloat32(0, x);
  const bits = view.getUint32(0);
  const exponentBits = bits >>> 23;
  const fraction = bits & 0x7fffff;
  const significand = BigInt(exponentBits === 0 ? fraction : fraction | 0x800000);
  const exponent2 = exponentBits === 0 ? -149 : exponentBits - 150;
  // In quarters of the last place: `x` is 4m of them, and its interval's ends
  // 2 either side, or 1 below a power of two, where the gap below is half.
  const quarters = 4n * significand;
  const below = fraction === 0 && exponentBits > 1 ? 1n : 2n;
  const even = (significand & 1n) === 0n;
  const quarterNum = exponent2 >= 2 ? 1n << BigInt(exponent2 - 2) : 1n;
  const quarterDen = exponent2 < 2 ? 1n << BigInt(2 - exponent2) : 1n;
  // `c` times 10 to `p`, against `k` quarters.
  const compare = (c, p, k) => {
    const left = p >= 0 ? c * 10n ** BigInt(p) * quarterDen : c * quarterDen;
    const right = p >= 0 ? k * quarterNum : k * quarterNum * 10n ** BigInt(-p);
    return left < right ? -1 : left > right ? 1 : 0;
  };
  const readsBack = (c, p) => {
    const low = compare(c, p, quarters - below);
    const high = compare(c, p, quarters + 2n);
    return (low > 0 || (low === 0 && even)) && (high < 0 || (high === 0 && even));
  };

  // The first digit's power of ten, estimated, then made exact.
  let exponent = Math.floor(Math.log10(x));
  while (compare(1n, exponent, quarters) > 0) exponent--;
  while (compare(1n, exponent + 1, quarters) <= 0) exponent++;

  for (let precision = 1; precision <= 9; precision++) {
    const power = exponent - precision + 1;
    // `x` over 10 to `power`, as `n / d`, and the integer nearest it.
    const n = power >= 0 ? quarters * quarterNum : quarters * quarterNum * 10n ** BigInt(-power);
    const d = power >= 0 ? quarterDen * 10n ** BigInt(power) : quarterDen;
    const rounded = n / d + (2n * (n % d) >= d ? 1n : 0n);
    let best;
    let bestDistance;
    for (const candidate of [rounded, rounded - 1n, rounded + 1n]) {
      if (candidate > 0n && readsBack(candidate, power)) {
        const delta = candidate * d - n;
        const distance = delta < 0n ? -delta : delta;
        if (best === undefined || distance < bestDistance || (distance === bestDistance && candidate > best)) {
          best = candidate;
          bestDistance = distance;
        }
      }
    }
    if (best !== undefined) {
      let digits = best.toString();
      let decimalPower = power;
      while (digits.endsWith("0")) {
        digits = digits.slice(0, -1);
        decimalPower++;
      }
      return [digits, digits.length + decimalPower];
    }
  }
  throw new Error("No f32 round-trip decimal found");
}

export function $displayF32(value) {
  if (Number.isNaN(value)) return "NaN";
  if (value === Infinity) return "inf";
  if (value === -Infinity) return "-inf";
  const sign = value < 0 || Object.is(value, -0) ? "-" : "";
  if (value === 0) return sign + "0";
  const [digits, point] = $f32Digits(Math.abs(value));
  const body =
    point <= 0
      ? "0." + "0".repeat(-point) + digits
      : point >= digits.length
        ? digits + "0".repeat(point - digits.length)
        : digits.slice(0, point) + "." + digits.slice(point);
  return sign + body;
}

export function $debugF32(value) {
  const size = Math.abs(value);
  if (Number.isFinite(value) && size !== 0 && (size < Math.fround(1e-4) || size >= Math.fround(1e16))) {
    const [digits, point] = $f32Digits(size);
    const mantissa = digits.length > 1 ? digits[0] + "." + digits.slice(1) : digits;
    return (value < 0 ? "-" : "") + mantissa + "e" + (point - 1);
  }
  const text = $displayF32(value);
  return Number.isFinite(value) && !text.includes(".") ? text + ".0" : text;
}

export function $bigToF32(n) {
  const negative = n < 0n;
  let size = negative ? -n : n;
  const length = size.toString(2).length;
  if (length > 24) {
    const shift = BigInt(length - 24);
    const rest = size & ((1n << shift) - 1n);
    const half = 1n << (shift - 1n);
    size >>= shift;
    if (rest > half || (rest === half && (size & 1n) === 1n)) size++;
    size <<= shift;
  }
  const x = Number(size);
  return negative ? -x : x;
}

export function $powiF32(x, n) {
  const reciprocal = n < 0;
  let result = 1;
  while (true) {
    if (n & 1) {
      result = Math.fround(result * x);
    }
    n = (n / 2) | 0;
    if (n === 0) {
      break;
    }
    x = Math.fround(x * x);
  }
  return reciprocal ? Math.fround(1 / result) : result;
}

export function $parseF32(s) {
  const read = $parseF64(s);
  const d = read._0;
  if (read.TAG === "Err" || !Number.isFinite(d) || Math.fround(d) === d) {
    return read.TAG === "Err" ? read : { TAG: "Ok", _0: Math.fround(d) };
  }
  const rounded = Math.fround(d);
  // The `f32` this side of `d`: the largest where it rounds to infinity.
  const near = Number.isFinite(rounded) ? rounded : Math.sign(d) * 3.4028234663852886e38;
  const size = Math.abs(near);
  // The `f32` on `d`'s other side, and the tie between them: past the
  // largest, where infinity is, it's as far above as the one below is.
  const view = new DataView(new ArrayBuffer(8));
  view.setFloat32(0, size);
  const bits = view.getUint32(0);
  view.setUint32(0, Math.abs(d) > size ? bits + 1 : bits - 1);
  const other = view.getFloat32(0);
  view.setUint32(0, bits - 1);
  const tie = other === Infinity ? size + (size - view.getFloat32(0)) / 2 : (size + other) / 2;
  if (Math.abs(d) !== tie) return { TAG: "Ok", _0: rounded };
  // The digits, `digits` times 10 to `exponent`, against the tie, `m`
  // times 2 to `k`, in integers.
  const [mantissa, power = "0"] = s.toLowerCase().replace(/^[+-]/, "").split("e");
  const [whole, fraction = ""] = mantissa.split(".");
  const digits = BigInt(whole + fraction || "0");
  const exponent = Number(power) - fraction.length;
  view.setFloat64(0, tie);
  const tieBits = view.getBigUint64(0);
  const m = (tieBits & ((1n << 52n) - 1n)) | (1n << 52n);
  const k = Number(tieBits >> 52n) - 1075;
  const left = digits * 10n ** BigInt(Math.max(exponent, 0)) * 2n ** BigInt(Math.max(-k, 0));
  const right = m * 2n ** BigInt(Math.max(k, 0)) * 10n ** BigInt(Math.max(-exponent, 0));
  // The tie itself goes to the even one, as `Math.fround` takes it.
  if (left === right) return { TAG: "Ok", _0: rounded };
  const chosen = left > right ? Math.max(size, other) : Math.min(size, other);
  return { TAG: "Ok", _0: d < 0 ? -chosen : chosen };
}

export function $f64Max(a, b) {
  return Number.isNaN(a) ? b : Number.isNaN(b) ? a : Math.max(a, b);
}

export function $f64Min(a, b) {
  return Number.isNaN(a) ? b : Number.isNaN(b) ? a : Math.min(a, b);
}

export function $div(a, b, min) {
  if (b === 0) {
    throw new Error("attempt to divide by zero");
  }
  if (a === min && b === -1) {
    throw new Error("attempt to divide with overflow");
  }
  return a / b;
}

export function $rem(a, b, min) {
  if (b === 0) {
    throw new Error("attempt to calculate the remainder with a divisor of zero");
  }
  if (a === min && b === -1) {
    throw new Error("attempt to calculate the remainder with overflow");
  }
  return a % b;
}

export function $retain(v, keep) {
  let n = 0;
  for (const x of v) {
    if (keep(x)) {
      v[n++] = x;
    }
  }
  v.length = n;
}

export function $debug(v) {
  if (typeof v === "string") {
    return JSON.stringify(v);
  }
  if (Array.isArray(v)) {
    return "[" + v.map($debug).join(", ") + "]";
  }
  if (v === undefined) {
    return "()";
  }
  // A `HashMap` and a `HashSet` (ADR 0059), in braces as Rust shows them.
  if (v instanceof Map) {
    return "{" + [...v].map(([k, x]) => $debug(k) + ": " + $debug(x)).join(", ") + "}";
  }
  if (v instanceof Set) {
    return "{" + [...v].map($debug).join(", ") + "}";
  }
  if (typeof v === "object" && v !== null) {
    return "{ " + Object.entries(v).map(([k, x]) => k + ": " + $debug(x)).join(", ") + " }";
  }
  return String(v);
}

export function $eq(a, b) {
  if (a === b || (a == null && b == null)) {
    return true;
  }
  if (typeof a !== "object" || typeof b !== "object" || a === null || b === null) {
    return false;
  }
  if (Array.isArray(a)) {
    return Array.isArray(b) && a.length === b.length && a.every((x, i) => $eq(x, b[i]));
  }
  const keys = Object.keys(a);
  return keys.length === Object.keys(b).length && keys.every((k) => $eq(a[k], b[k]));
}

// `left` and `right` are their `{:?}` strings already (ADR 0060).
export function $assertFailed(kind, left, right, message) {
  const op = kind === "Eq" ? "==" : kind === "Ne" ? "!=" : "matches";
  const why = message === undefined ? "" : ": " + message;
  throw new Error("assertion `left " + op + " right` failed" + why + "\n  left: " + left + "\n right: " + right);
}

export function $unwrap(value, message = "called `Option::unwrap()` on a `None` value") {
  if (value == null) {
    throw new Error(message);
  }
  return value;
}

// `Some(x)` of a generic `T` (ADR 0051): `x`, unless it looks like `None`,
// as `undefined`, `null` or such a box does. Then it's a box one deeper.
export function $some(x) {
  if (x == null) return { $someNone: 0 };
  if (typeof x === "object" && "$someNone" in x) return { $someNone: x.$someNone + 1 };
  return x;
}

// What's in a `$some`: the box one level shallower.
export function $someValue(x) {
  if (x != null && typeof x === "object" && "$someNone" in x) {
    return x.$someNone === 0 ? undefined : { $someNone: x.$someNone - 1 };
  }
  return x;
}

// `Some` of the item at `index`, or `None` when there's none there.
export function $someAt(items, index) {
  return index >= 0 && index < items.length ? $some(items[index]) : undefined;
}

// `Vec::pop` of a generic `T`: `None` for an empty one, else `Some` of the last.
export function $pop(items) {
  return items.length === 0 ? undefined : $some(items.pop());
}

// A Rust iterator of the crate's own as a JS one: its `next` returns the
// item, or `None` at the end. JS's iterator helpers are lazy, like Rust's
// adapters, so an endless one is fine until something wants all of it. A
// generic `next` may box its `Some` (ADR 0051): `boxed` unboxes it.
export function $iterator(iterator, next, boxed = false) {
  return Iterator.from({
    next() {
      const item = next(iterator);
      if (item == null) {
        return { done: true, value: undefined };
      }
      return { done: false, value: boxed ? $someValue(item) : item };
    }
  });
}

export function $insert(map, key, value) {
  const old = map.get(key);
  map.set(key, value);
  return old;
}

export function $add(set, item) {
  const added = !set.has(item);
  set.add(item);
  return added;
}

export function $remove(map, key) {
  const old = map.get(key);
  map.delete(key);
  return old;
}

export function $repeat(item, count, clone) {
  const result = [];
  if (count > 0) {
    for (let i = 1; i < count; i++) result.push(clone(item));
    result.push(item);
  }
  return result;
}

export function $orInsert(map, key, value) {
  if (!map.has(key)) {
    map.set(key, value);
  }
  return map.get(key);
}

export function $orInsertWith(map, key, make) {
  if (!map.has(key)) {
    map.set(key, make());
  }
  return map.get(key);
}

export function $key(value) {
  if (value == null) {
    return "~";
  }
  switch (typeof value) {
    case "string":
      return JSON.stringify(value);
    case "bigint":
      return value + "n";
    case "object":
      if (Array.isArray(value)) {
        return "[" + value.map($key).join(",") + "]";
      }
      return "{" + Object.keys(value).sort().map((k) => JSON.stringify(k) + ":" + $key(value[k])).join(",") + "}";
    default:
      return String(value);
  }
}

export class $KeyMap extends Map {
  constructor(entries) {
    super();
    if (entries) {
      for (const [key, value] of entries) {
        this.set(key, value);
      }
    }
  }
  get(key) {
    const entry = super.get($key(key));
    return entry === undefined ? undefined : entry[1];
  }
  set(key, value) {
    const found = $key(key);
    const entry = super.get(found);
    if (entry === undefined) {
      super.set(found, [key, value]);
    } else {
      entry[1] = value;
    }
    return this;
  }
  has(key) {
    return super.has($key(key));
  }
  delete(key) {
    return super.delete($key(key));
  }
  *entries() {
    for (const [key, value] of super.values()) {
      yield [key, value];
    }
  }
  *keys() {
    for (const [key] of super.values()) {
      yield key;
    }
  }
  *values() {
    for (const [, value] of super.values()) {
      yield value;
    }
  }
  [Symbol.iterator]() {
    return this.entries();
  }
  forEach(f, that) {
    for (const [key, value] of this.entries()) {
      f.call(that, value, key, this);
    }
  }
}

export class $KeySet extends Set {
  #items = new Map();
  constructor(items) {
    super();
    if (items) {
      for (const item of items) {
        this.add(item);
      }
    }
  }
  get size() {
    return this.#items.size;
  }
  add(item) {
    const found = $key(item);
    if (!this.#items.has(found)) {
      this.#items.set(found, item);
    }
    return this;
  }
  has(item) {
    return this.#items.has($key(item));
  }
  delete(item) {
    return this.#items.delete($key(item));
  }
  clear() {
    this.#items.clear();
  }
  values() {
    return this.#items.values();
  }
  keys() {
    return this.#items.values();
  }
  *entries() {
    for (const item of this.#items.values()) {
      yield [item, item];
    }
  }
  [Symbol.iterator]() {
    return this.#items.values();
  }
  forEach(f, that) {
    for (const item of this.#items.values()) {
      f.call(that, item, item, this);
    }
  }
}

export function $sortedEntries(map, cmp) {
  return Array.from(map).sort((a, b) => cmp(a[0], b[0]));
}

export function $toDigit(c, radix) {
  const digit = parseInt(c, 36);
  return digit < radix ? digit : undefined;
}

export function $lines(s) {
  const lines = s.split("\n");
  const last = lines.pop();
  const ended = lines.map((line) => (line.endsWith("\r") ? line.slice(0, -1) : line));
  if (last !== "") {
    ended.push(last);
  }
  return ended;
}

export function $splitBy(s, matches) {
  const pieces = [""];
  for (const c of s) {
    if (matches(c)) {
      pieces.push("");
    } else {
      pieces[pieces.length - 1] += c;
    }
  }
  return pieces;
}

export function $pow(base, exp) {
  let result = 1;
  while (exp > 0) {
    if (exp & 1) {
      result = Math.imul(result, base);
    }
    base = Math.imul(base, base);
    exp >>>= 1;
  }
  return result;
}

export function $checkedPow(base, exp, lo, hi) {
  const fits = (x) => x >= lo && x <= hi;
  const result = (x) => (typeof hi === "bigint" ? x : Number(x));
  if (exp === 0) return result(1n);
  let b = BigInt(base);
  let acc = 1n;
  while (exp > 1) {
    if (exp & 1) {
      acc *= b;
      if (!fits(acc)) return undefined;
    }
    exp >>>= 1;
    b *= b;
    if (!fits(b)) return undefined;
  }
  acc *= b;
  return fits(acc) ? result(acc) : undefined;
}

export function $powi(x, n) {
  const reciprocal = n < 0;
  let result = 1;
  while (true) {
    if (n & 1) {
      result *= x;
    }
    n = (n / 2) | 0;
    if (n === 0) {
      break;
    }
    x *= x;
  }
  return reciprocal ? 1 / result : result;
}

export function $round(x) {
  return Math.sign(x) * Math.round(Math.abs(x));
}

export function $checked(value, lo, hi) {
  return value >= lo && value <= hi ? value + 0 : undefined;
}

export function $checkedDiv(a, b, min) {
  return b === 0 || (a === min && b === -1) ? undefined : Math.trunc(a / b) + 0;
}

export function $remEuclid(a, b, min) {
  const r = $rem(a, b, min) + 0;
  return r < 0 ? (b < 0 ? r - b : r + b) : r;
}

export function $divEuclid(a, b, min) {
  const q = Math.trunc($div(a, b, min)) + 0;
  return a % b < 0 ? (b > 0 ? q - 1 : q + 1) : q;
}

export function $trailingZeros(x, bits) {
  return x === 0 ? bits : 31 - Math.clz32(x & -x);
}

export function $countOnes(x) {
  let ones = 0;
  x >>>= 0;
  while (x !== 0) {
    ones += x & 1;
    x >>>= 1;
  }
  return ones;
}

export function $binarySearch(items, x) {
  let size = items.length;
  if (size === 0) {
    return { TAG: "Err", _0: 0 };
  }
  let base = 0;
  while (size > 1) {
    const half = size >>> 1;
    const mid = base + half;
    if (!(items[mid] > x)) {
      base = mid;
    }
    size -= half;
  }
  const found = items[base];
  return found === x ? { TAG: "Ok", _0: base } : { TAG: "Err", _0: base + (found < x ? 1 : 0) };
}

export function $removeOpt(items, index) {
  return index < items.length ? items.splice(index, 1)[0] : undefined;
}

export function $iter(items) {
  return {
    items,
    at: 0,
    next() {
      return this.at < this.items.length ? { value: this.items[this.at++], done: false } : { value: undefined, done: true };
    },
    [Symbol.iterator]() {
      return this;
    },
  };
}

