export function $siftUp(heap, start, pos, cmp) {
  const item = heap[pos];
  while (pos > start) {
    const parent = (pos - 1) >>> 1;
    if (cmp(item, heap[parent]) <= 0) {
      break;
    }
    heap[pos] = heap[parent];
    pos = parent;
  }
  heap[pos] = item;
  return pos;
}

export function $siftDown(heap, pos, end, cmp) {
  const item = heap[pos];
  let child = 2 * pos + 1;
  while (child <= end - 2) {
    if (cmp(heap[child], heap[child + 1]) <= 0) {
      child += 1;
    }
    if (cmp(item, heap[child]) >= 0) {
      heap[pos] = item;
      return pos;
    }
    heap[pos] = heap[child];
    pos = child;
    child = 2 * pos + 1;
  }
  if (child === end - 1 && cmp(item, heap[child]) < 0) {
    heap[pos] = heap[child];
    pos = child;
  }
  heap[pos] = item;
  return pos;
}

